#!/bin/sh
# The bindings are generated by the flake (rustBindings in flake.nix: the engine's per-arch headers,
# the flake's bindgen and rustfmt, on x86_64-linux), and `nix flake check` fails when the checked-in
# copy differs. Regenerate after changing an engine header:
set -e
cd "$(dirname "$0")/../.."
exec nix run .#regen-rust-bindings
